mapper.sql:
SELECT b.bill_id,b.prj_id,b.bill_stg_id,b.bill_odr_no,b.atrb_ym,b.bill_dt,b.sply_amt,b.vat_amt,
  b.bill_stts_cd,b.txinv_no,b.txinv_dt,b.amnd_yn,b.orgnl_bill_id,b.rcpt_plan_dt,b.rmrk_desc,b.created_at
FROM bill.bill b WHERE b.bill_id=#{id}

WHERE LEFT(b.view_month,4)=CAST(#{year} AS text)
AND b.bill_stts_cd=#{status}
AND b.contract_type=#{type}
AND b.customer_id=#{customerId}
AND (b.project_name ILIKE '%' || #{q} || '%' OR b.bill_no ILIKE '%' || #{q} || '%')

mapper.select:
 SELECT b.* FROM billing_rows b 
ORDER BY b.${orderBy} ${direction} NULLS LAST,b.bill_id DESC NULLS LAST,b.bill_stg_id DESC
LIMIT #{size} OFFSET #{offset}
